import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Video Recordings (Analyze View)","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/analyze_view/video_recordings.md","filePath":"en/qgc-user-guide/analyze_view/video_recordings.md"}`),a={name:`en/qgc-user-guide/analyze_view/video_recordings.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="video-recordings-analyze-view" tabindex="-1">Video Recordings (Analyze View) <a class="header-anchor" href="#video-recordings-analyze-view" aria-label="Permalink to “Video Recordings (Analyze View)”">​</a></h1><p>The Video Recordings page (<strong>Analyze &gt; Video Recordings</strong>) plays the videos <em>QGroundControl</em> recorded, from the video stream or a USB camera (see <a href="./../fly_view/video.html#record-video-stream-on-gcs">Record Video Stream</a>), with the telemetry recorded alongside them.</p><p>The recordings in the video folder of the <a href="./../settings_view/general.html#load-save-path">Application Load/Save Path</a> are listed newest first, with their size and time. Select one to play it:</p><ul><li><strong>Play</strong> / <strong>Pause</strong> — start and pause playback, as do clicking the video and the space bar. Drag the bar to move through the video, or press the left and right arrow keys to move 5 seconds back or forward.</li><li><strong>Speed</strong> — play at half, normal or double speed (<strong>0.5x</strong>, <strong>1x</strong>, <strong>2x</strong>).</li><li><strong>Telemetry</strong> — show or hide the telemetry of the recording&#39;s <a href="./../fly_view/video_overlay.html">subtitle file</a>, drawn over the video where a player draws the subtitles. Shown only for a recording that has one.</li><li><strong>Delete</strong> — delete the recording and its subtitle file, after you confirm.</li></ul><p>The list follows recordings being added or deleted while the page is open.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};